"use client"

import * as React from "react"
import * as RechartsPrimitive from "recharts"
import type { TooltipValueType } from "recharts"

import { cn } from "@/lib/utils"
import "../styles/brutalist.css"

// Format: { THEME_NAME: CSS_SELECTOR }
const THEMES = { light: "", dark: ".dark" } as const

const INITIAL_DIMENSION = { width: 320, height: 200 } as const
type TooltipNameType = number | string

export type ChartConfig = Record<
  string,
  {
    label?: React.ReactNode
    icon?: React.ComponentType
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
>

type ChartContextProps = {
  config: ChartConfig
}

const ChartContext = React.createContext<ChartContextProps | null>(null)

function useChart() {
  const context = React.useContext(ChartContext)

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />")
  }

  return context
}

function ChartContainer({
  id,
  className,
  children,
  config,
  initialDimension = INITIAL_DIMENSION,
  ...props
}: React.ComponentProps<"div"> & {
  config: ChartConfig
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"]
  initialDimension?: {
    width: number
    height: number
  }
}) {
  const uniqueId = React.useId()
  const chartId = `chart-${id ?? uniqueId.replace(/:/g, "")}`

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "flex aspect-video justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-hidden [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector]:outline-hidden [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-surface]:outline-hidden",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer
          initialDimension={initialDimension}
        >
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  )
}

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme ?? config.color
  )

  if (!colorConfig.length) {
    return null
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ??
      itemConfig.color
    return color ? `  --color-${key}: ${color};` : null
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  )
}

const ChartTooltip = RechartsPrimitive.Tooltip

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  color,
  nameKey,
  labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  React.ComponentProps<"div"> & {
    hideLabel?: boolean
    hideIndicator?: boolean
    indicator?: "line" | "dot" | "dashed"
    nameKey?: string
    labelKey?: string
  } & Omit<
    RechartsPrimitive.DefaultTooltipContentProps<
      TooltipValueType,
      TooltipNameType
    >,
    "accessibilityLayer"
  >) {
  const { config } = useChart()

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null
    }

    const [item] = payload
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`
    const itemConfig = getPayloadConfigFromPayload(config, item, key)
    const value =
      !labelKey && typeof label === "string"
        ? (config[label]?.label ?? label)
        : itemConfig?.label

    if (labelFormatter) {
      return (
        <div className={cn("font-medium", labelClassName)}>
          {labelFormatter(value, payload)}
        </div>
      )
    }

    if (!value) {
      return null
    }

    return <div className={cn("font-medium", labelClassName)}>{value}</div>
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelClassName,
    config,
    labelKey,
  ])

  if (!active || !payload?.length) {
    return null
  }

  const nestLabel = payload.length === 1 && indicator !== "dot"

  return (
    <div
      className={cn(
        "brut-popover grid min-w-36 items-start gap-2 bg-popover px-3 py-2 text-xs font-semibold text-popover-foreground",
        className
      )}
    >
      {!nestLabel ? tooltipLabel : null}
      <div className="grid gap-1.5">
        {payload
          .filter((item) => item.type !== "none")
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`
            const itemConfig = getPayloadConfigFromPayload(config, item, key)
            const indicatorColor = color ?? item.payload?.fill ?? item.color

            return (
              <div
                key={index}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center"
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn(
                            "shrink-0 rounded-[2px] border-(--color-border) bg-(--color-bg)",
                            {
                              "h-2.5 w-2.5": indicator === "dot",
                              "w-1": indicator === "line",
                              "w-0 border-[1.5px] border-dashed bg-transparent":
                                indicator === "dashed",
                              "my-0.5": nestLabel && indicator === "dashed",
                            }
                          )}
                          style={
                            {
                              "--color-bg": indicatorColor,
                              "--color-border": indicatorColor,
                            } as React.CSSProperties
                          }
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center"
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">
                          {itemConfig?.label ?? item.name}
                        </span>
                      </div>
                      {item.value != null && (
                        <span className="font-mono font-medium text-foreground tabular-nums">
                          {typeof item.value === "number"
                            ? item.value.toLocaleString()
                            : String(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            )
          })}
      </div>
    </div>
  )
}

const ChartLegend = RechartsPrimitive.Legend

function ChartLegendContent({
  className,
  hideIcon = false,
  payload,
  verticalAlign = "bottom",
  nameKey,
}: React.ComponentProps<"div"> & {
  hideIcon?: boolean
  nameKey?: string
} & RechartsPrimitive.DefaultLegendContentProps) {
  const { config } = useChart()

  if (!payload?.length) {
    return null
  }

  return (
    <div
      className={cn(
        "flex items-center justify-center gap-4",
        verticalAlign === "top" ? "pb-3" : "pt-3",
        className
      )}
    >
      {payload
        .filter((item) => item.type !== "none")
        .map((item, index) => {
          const key = `${nameKey ?? item.dataKey ?? "value"}`
          const itemConfig = getPayloadConfigFromPayload(config, item, key)

          return (
            <div
              key={index}
              className={cn(
                "flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3 [&>svg]:text-muted-foreground"
              )}
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                <div
                  className="h-2 w-2 shrink-0 rounded-[2px]"
                  style={{
                    backgroundColor: item.color,
                  }}
                />
              )}
              {itemConfig?.label}
            </div>
          )
        })}
    </div>
  )
}

function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string
) {
  if (typeof payload !== "object" || payload === null) {
    return undefined
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined

  let configLabelKey: string = key

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string
  }

  return configLabelKey in config ? config[configLabelKey] : config[key]
}

export {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
  ChartLegend,
  ChartLegendContent,
  ChartStyle,
}

:root,
[data-brut-palette="paper"] {
  --background: oklch(0.985 0.004 95);
  --foreground: oklch(0.15 0.01 65);
  --card: oklch(1 0 0);
  --card-foreground: var(--foreground);
  --popover: oklch(1 0 0);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.82 0.18 88);
  --primary-foreground: oklch(0.13 0.01 70);
  --secondary: oklch(0.88 0.105 210);
  --secondary-foreground: oklch(0.13 0.01 70);
  --muted: oklch(0.94 0.018 90);
  --muted-foreground: oklch(0.38 0.02 65);
  --accent: oklch(0.72 0.2 20);
  --accent-foreground: oklch(0.99 0 0);
  --destructive: oklch(0.61 0.24 28);
  --border: oklch(0.15 0.01 65);
  --input: oklch(0.15 0.01 65);
  --ring: oklch(0.56 0.23 264);
  --brut-shadow-color: oklch(0.15 0.01 65);
}

:root {
  --chart-1: var(--primary);
  --chart-2: var(--secondary);
  --chart-3: var(--accent);
  --chart-4: var(--destructive);
  --chart-5: var(--muted-foreground);
  --sidebar: var(--card);
  --sidebar-foreground: var(--card-foreground);
  --sidebar-primary: var(--primary);
  --sidebar-primary-foreground: var(--primary-foreground);
  --sidebar-accent: var(--accent);
  --sidebar-accent-foreground: var(--accent-foreground);
  --sidebar-border: var(--border);
  --sidebar-ring: var(--ring);
}

[data-brut-palette="signal"] {
  --background: oklch(0.91 0.16 96);
  --foreground: oklch(0.13 0.01 70);
  --card: oklch(0.985 0.025 96);
  --card-foreground: var(--foreground);
  --popover: oklch(0.985 0.025 96);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.15 0.01 70);
  --primary-foreground: oklch(0.93 0.17 96);
  --secondary: oklch(0.73 0.2 28);
  --secondary-foreground: oklch(0.13 0.01 70);
  --muted: oklch(0.86 0.11 96);
  --muted-foreground: oklch(0.31 0.03 70);
  --accent: oklch(0.75 0.13 222);
  --accent-foreground: oklch(0.13 0.01 70);
  --destructive: oklch(0.55 0.24 28);
  --border: oklch(0.13 0.01 70);
  --input: oklch(0.13 0.01 70);
  --ring: oklch(0.55 0.24 28);
  --brut-shadow-color: oklch(0.13 0.01 70);
}

[data-brut-palette="sky"] {
  --background: oklch(0.92 0.055 235);
  --foreground: oklch(0.16 0.04 255);
  --card: oklch(0.98 0.018 230);
  --card-foreground: var(--foreground);
  --popover: oklch(0.985 0.018 230);
  --popover-foreground: var(--foreground);
  --primary: oklch(0.52 0.2 255);
  --primary-foreground: oklch(0.99 0 0);
  --secondary: oklch(0.88 0.16 92);
  --secondary-foreground: oklch(0.16 0.04 255);
  --muted: oklch(0.86 0.045 235);
  --muted-foreground: oklch(0.36 0.055 255);
  --accent: oklch(0.71 0.18 28);
  --accent-foreground: oklch(0.16 0.04 255);
  --destructive: oklch(0.56 0.24 27);
  --border: oklch(0.16 0.04 255);
  --input: oklch(0.16 0.04 255);
  --ring: oklch(0.67 0.2 28);
  --brut-shadow-color: oklch(0.16 0.04 255);
}

:root,
[data-brut-strength="solid"] {
  --brut-border: 2px;
  --brut-shadow-x: 4px;
  --brut-shadow-y: 4px;
  --brut-panel-shadow-x: 7px;
  --brut-panel-shadow-y: 7px;
  --brut-slider-track: 4px;
  --brut-hover: -1px;
  --brut-press: 2px;
  --brut-weight: 700;
}

[data-brut-strength="soft"] {
  --brut-border: 1px;
  --brut-shadow-x: 2px;
  --brut-shadow-y: 2px;
  --brut-panel-shadow-x: 4px;
  --brut-panel-shadow-y: 4px;
  --brut-slider-track: 2px;
  --brut-hover: -1px;
  --brut-press: 1px;
  --brut-weight: 600;
}

[data-brut-strength="loud"] {
  --brut-border: 3px;
  --brut-shadow-x: 6px;
  --brut-shadow-y: 6px;
  --brut-panel-shadow-x: 9px;
  --brut-panel-shadow-y: 9px;
  --brut-slider-track: 6px;
  --brut-hover: -2px;
  --brut-press: 3px;
  --brut-weight: 800;
}

:root,
[data-brut-radius="sharp"] {
  --radius: 0rem;
}

[data-brut-radius="cut"] {
  --radius: 0.375rem;
}

[data-brut-radius="chunky"] {
  --radius: 0.875rem;
}

@layer base {
  * {
    border-color: var(--border);
    outline-color: color-mix(in oklab, var(--ring) 60%, transparent);
  }

  html {
    scroll-behavior: smooth;
  }

  body {
    background-color: var(--background);
    color: var(--foreground);
  }

  ::selection {
    background: var(--primary);
    color: var(--primary-foreground);
  }
}

@layer components {
  .brut-panel {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-panel-shadow-x) var(--brut-panel-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-surface {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-control {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
    font-weight: var(--brut-weight);
    transition: transform 120ms ease, box-shadow 120ms ease, background-color 120ms ease;
  }

  .brut-control:hover:not(:disabled, [data-disabled]) {
    transform: translate(var(--brut-hover), var(--brut-hover));
    box-shadow: calc(var(--brut-shadow-x) - var(--brut-hover)) calc(var(--brut-shadow-y) - var(--brut-hover)) 0 var(--brut-shadow-color);
  }

  .brut-control:active:not(:disabled, [data-disabled]),
  .brut-control[data-pressed] {
    transform: translate(var(--brut-press), var(--brut-press));
    box-shadow: 0 0 0 var(--brut-shadow-color);
  }

  .brut-quiet {
    border: var(--brut-border) solid transparent;
    border-radius: var(--radius);
    box-shadow: none;
    font-weight: var(--brut-weight);
  }

  .brut-quiet:hover {
    border-color: var(--border);
    background: var(--muted);
  }

  .brut-focus:focus-visible {
    outline: 3px solid var(--ring);
    outline-offset: 3px;
  }

  .brut-input {
    border: var(--brut-border) solid var(--input);
    border-radius: var(--radius);
    background: var(--card);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
    font-weight: 600;
    transition: box-shadow 120ms ease, transform 120ms ease;
  }

  .brut-input:focus-visible {
    outline: 3px solid var(--ring);
    outline-offset: 2px;
    transform: translate(-1px, -1px);
    box-shadow: calc(var(--brut-shadow-x) + 2px) calc(var(--brut-shadow-y) + 2px) 0 var(--brut-shadow-color);
  }

  .brut-input-group {
    border: var(--brut-border) solid var(--input);
    border-radius: var(--radius);
    background: var(--card);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
    font-weight: 600;
    transition: box-shadow 120ms ease, transform 120ms ease;
  }

  .brut-input-group:focus-within {
    outline: 3px solid var(--ring);
    outline-offset: 2px;
    transform: translate(-1px, -1px);
    box-shadow: calc(var(--brut-shadow-x) + 2px) calc(var(--brut-shadow-y) + 2px) 0 var(--brut-shadow-color);
  }

  .brut-input-group:has([aria-invalid="true"]) {
    border-color: var(--destructive);
  }

  .brut-input-group:has([aria-invalid="true"]):focus-within {
    outline-color: var(--destructive);
  }

  .brut-otp-group:has([data-active="true"]) {
    outline: 3px solid var(--ring);
    outline-offset: 2px;
    transform: translate(-1px, -1px);
    box-shadow: calc(var(--brut-shadow-x) + 2px) calc(var(--brut-shadow-y) + 2px) 0 var(--brut-shadow-color);
  }

  .brut-otp-group:has([aria-invalid="true"]) {
    border-color: var(--destructive);
  }

  .brut-otp-group:has([aria-invalid="true"]):has([data-active="true"]) {
    outline-color: var(--destructive);
  }

  .brut-chip {
    border: var(--brut-border) solid var(--border);
    border-radius: calc(var(--radius) * 0.75);
    box-shadow: none;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  .brut-toggle {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: none;
    font-weight: var(--brut-weight);
  }

  .brut-kbd {
    border: var(--brut-border) solid var(--border);
    border-radius: calc(var(--radius) * 0.6);
    box-shadow: none;
    font-weight: var(--brut-weight);
  }

  .brut-item {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: none;
  }

  .brut-accordion-item:not(:last-child) {
    border-bottom: var(--brut-border) solid var(--border);
    box-shadow: none;
  }

  .brut-check {
    border: var(--brut-border) solid var(--border);
    border-radius: calc(var(--radius) * 0.5);
    background: var(--card);
    box-shadow: 2px 2px 0 var(--brut-shadow-color);
  }

  .brut-radio {
    border: var(--brut-border) solid var(--input);
  }

  .brut-slider-thumb {
    border: var(--brut-border) solid var(--ring);
  }

  .brut-menubar {
    border: var(--brut-border) solid var(--border);
  }

  .brut-avatar {
    border: var(--brut-border) solid var(--border);
    background: var(--card);
    box-shadow: calc(var(--brut-border) + 1px) calc(var(--brut-border) + 1px) 0 var(--brut-shadow-color);
  }

  .brut-separator {
    background: var(--border);
  }

  .brut-dialog {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-panel-shadow-x) var(--brut-panel-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-questionnaire-choice {
    border: var(--brut-border) solid var(--input);
    border-radius: var(--radius);
  }

  .brut-sheet[data-side="right"] {
    border-left: var(--brut-border) solid var(--border);
    border-radius: var(--radius) 0 0 var(--radius);
    box-shadow: calc(0px - var(--brut-panel-shadow-x)) 0 0 var(--brut-shadow-color);
  }

  .brut-sheet[data-side="left"] {
    border-right: var(--brut-border) solid var(--border);
    border-radius: 0 var(--radius) var(--radius) 0;
    box-shadow: var(--brut-panel-shadow-x) 0 0 var(--brut-shadow-color);
  }

  .brut-sheet[data-side="bottom"] {
    border-top: var(--brut-border) solid var(--border);
    border-radius: var(--radius) var(--radius) 0 0;
    box-shadow: 0 calc(0px - var(--brut-panel-shadow-y)) 0 var(--brut-shadow-color);
  }

  .brut-sheet[data-side="top"] {
    border-bottom: var(--brut-border) solid var(--border);
    border-radius: 0 0 var(--radius) var(--radius);
    box-shadow: 0 var(--brut-panel-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-drawer[data-swipe-direction="down"] {
    border-top: var(--brut-border) solid var(--border);
    border-radius: var(--radius) var(--radius) 0 0;
    box-shadow: 0 calc(0px - var(--brut-panel-shadow-y)) 0 var(--brut-shadow-color);
  }

  .brut-drawer[data-swipe-direction="up"] {
    border-bottom: var(--brut-border) solid var(--border);
    border-radius: 0 0 var(--radius) var(--radius);
    box-shadow: 0 var(--brut-panel-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-drawer[data-swipe-direction="left"] {
    border-right: var(--brut-border) solid var(--border);
    border-radius: 0 var(--radius) var(--radius) 0;
    box-shadow: var(--brut-panel-shadow-x) 0 0 var(--brut-shadow-color);
  }

  .brut-drawer[data-swipe-direction="right"] {
    border-left: var(--brut-border) solid var(--border);
    border-radius: var(--radius) 0 0 var(--radius);
    box-shadow: calc(0px - var(--brut-panel-shadow-x)) 0 0 var(--brut-shadow-color);
  }

  .brut-popover {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: var(--brut-shadow-x) var(--brut-shadow-y) 0 var(--brut-shadow-color);
  }

  .brut-switch {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    box-shadow: 3px 3px 0 var(--brut-shadow-color);
  }

  .brut-switch-thumb {
    border-radius: calc(var(--radius) * 0.75);
  }

  .brut-progress {
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    background: var(--card);
  }

  .brut-resizable-group {
    overflow: hidden;
    border: var(--brut-border) solid var(--border);
    border-radius: var(--radius);
    background: var(--card);
  }

  .brut-resizable-handle {
    width: var(--brut-border);
    background: var(--border);
  }

  .brut-resizable-handle[aria-orientation="horizontal"] {
    width: 100%;
    height: var(--brut-border);
  }

  .brut-resizable-grip {
    border: var(--brut-border) solid var(--border);
    border-radius: min(var(--radius), 0.375rem);
    background: var(--card);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
